package com.bank.ordercheck;

import java.math.BigDecimal;
import java.util.Comparator;
import java.util.logging.Logger;

// Verifies settlement-file ordering for National Bank of India.
public class OrderCheckService {
    private static final Logger log = Logger.getLogger(OrderCheckService.class.getName());

    // Generic: sorted according to the supplied comparator. O(n), fail-fast.
    public boolean isSorted(BigDecimal[] values, Comparator<BigDecimal> cmp) {
        if (values == null || values.length < 2) {
            return true;                          // empty/single is trivially sorted
        }
        for (int i = 0; i < values.length - 1; i++) {
            if (cmp.compare(values[i], values[i + 1]) > 0) {
                final int idx = i;
                log.warning(() -> "Out of order at index " + idx
                        + ": " + values[idx] + " then " + values[idx + 1]);
                return false;                     // fail fast on first violation
            }
        }
        log.info("Array is sorted for the given order");
        return true;
    }

    // Non-strict ascending (equal neighbours allowed).
    public boolean isAscending(BigDecimal[] values) {
        return isSorted(values, Comparator.naturalOrder());
    }

    // Descending.
    public boolean isDescending(BigDecimal[] values) {
        return isSorted(values, Comparator.reverseOrder());
    }
}
