package com.bank.ordercheck;

import java.math.BigDecimal;
import java.util.logging.ConsoleHandler;
import java.util.logging.Logger;

// Runnable demo: verify settlement-file and report ordering.
public class OrderCheckDemo {
    private static final Logger log = Logger.getLogger(OrderCheckDemo.class.getName());

    static {
        Logger root = Logger.getLogger("");
        for (var h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler handler = new ConsoleHandler();
        handler.setFormatter(new BankLogFormatter());
        root.addHandler(handler);
    }

    private static BigDecimal[] of(String... xs) {
        BigDecimal[] a = new BigDecimal[xs.length];
        for (int i = 0; i < xs.length; i++) a[i] = new BigDecimal(xs[i]);
        return a;
    }

    public static void main(String[] args) {
        OrderCheckService service = new OrderCheckService();

        BigDecimal[] goodTimes = of("1001", "1001", "1050", "1099");  // ties allowed
        BigDecimal[] badTimes  = of("1001", "1200", "1150", "1300");  // 1200 then 1150
        BigDecimal[] descReport = of("99000", "50000", "9000");

        log.info(() -> "Settlement file sorted ascending? " + service.isAscending(goodTimes));
        log.info(() -> "Corrupt file sorted ascending? " + service.isAscending(badTimes));
        log.info(() -> "Report sorted descending? " + service.isDescending(descReport));
    }
}
